		return b
	}
	n1 := n - 1
	n2 := n
	n3 := n1
	c := uint64(1)
	d := (n3 + b) / n2
	e := (n3*d + b/pow(d, n1)) / n2
	for c != d && c != e {
		c = d
		d = e
		e = (n3*e + b/pow(e, n1)) / n2
	}
	if d < e {
		return d
	}
